  ep58OpenInstruction: "Invite Lingua to do something.",
  ep58ListenInstruction: "Listen to the reply. What is being asked about?",
  ep58AgainInstruction: "Invite Lingua to do something else, on a different day.",
  ep58FinalInstruction: "One more time, unaided — invite somebody to do something.",
  ep58CloseTitle: "Invitation sent",
