  ep59CompOptWrong2: "A question, not an answer.",
  ep59BlankInstruction: "Fill in the missing word.",
  ep59BlankHint: "What is the reason for saying no?",
  ep59ChoiceInstruction: "Which one is a decline?",
  ep59AcceptInstruction: "Accept the invitation.",
  ep59DeclineInstruction: "You can't make it. Decline — and say why.",
  ep59InsistInstruction: "They are asking again, about a different day. Answer once more.",
  ep59FinalInstruction: "One more time, unaided — decline, with a reason.",
  ep59CloseTitle: "Answered honestly",
  ep59CloseBody: "You can now accept or decline an invitation — and a decline always comes with a reason.",
  ep60Title: "And then...",
  ep60Goal: "Keep the conversation going after the plan is settled.",
  ep60CanDoName: "Keep a longer conversation going",
  ep60Duration: "10 min",
  ep60RecallInstruction: "Remember: how do you decline an invitation, with a reason?",
  ep60SceneTitle: "Not quite finished",
  ep60SceneBody: "The plan is almost settled — but the conversation isn't quite over yet.",
  ep60Start: "Let's go",
