  ep60CompOptCorrect: "Liking the idea, and needing to check the time.",
  ep60CompOptWrong1: "Two separate, unrelated ideas.",
  ep60CompOptWrong2: "A single idea, repeated twice.",
  ep60MeaningInstruction: "You don't understand a word Lingua used. What do you ask?",
  ep60BlankInstruction: "Fill in the missing connector.",
  ep60BlankHint: "It links two ideas that don't quite match.",
  ep60OpenInstruction: "Accept the invitation, and add a related thought.",
  ep60ConnectInstruction: "The topic just changed. Answer, and connect your reply to what was just said.",
  ep60FinalInstruction: "One more time, unaided — hold two connected ideas in one turn.",
  ep60CloseTitle: "Conversation kept going",
  ep60CloseBody: "You can now keep talking past the first answer, connecting one idea to the next.",
  ep61Title: "Let's do something else",
  ep61Goal: "Hold a whole plan-making conversation, unaided — including a change of plan.",
  ep61CanDoName: "Accept or decline with a reason",
  ep61Duration: "14 min",
  ep61RecallInstruction: "Before we start — without looking back, what did you do recently?",
  ep61SceneTitle: "One more plan",
  ep61SceneBody: "It's the weekend again. Let's see everything you can do now.",
  ep61Start: "Let's go",
  ep61OpenInstruction: "It's Friday, and you haven't made a plan yet. Open the conversation.",
