  ep61CompOptWrong1: "The plan is confirmed.",
  ep61CompOptWrong2: "Nothing has changed.",
  ep61StoryInstruction: "Here is the whole conversation, from invitation to confirmation.",
  ep61AdaptInstruction: "The original idea fell through. What do you say?",
  ep61ProposeInstruction: "What do you say now? Suggest something.",
  ep61ConnectInstruction: "The topic just changed. Answer, and connect your reply to what was just said.",
  ep61ConfirmInstruction: "Confirm the plan.",
  ep61CloseInstruction: "Close the conversation warmly.",
  ep61FinalInstruction: "Without looking back — what was the whole plan, from start to finish?",
  ep61CloseTitle: "A2 complete",
  ep61CloseBody: "You opened a conversation nobody scripted for you, declined one you genuinely couldn't do, and kept talking past the first 'no'. That's connected, everyday communication.",
  ep61CloseCta: "Finish",
