  b1RetryPromptNegotiateFrame: "Try \"would it be possible to...\" or \"could I possibly...\".",
  b1Ep15Title: "What's the Plan",
  b1Ep15Goal: "Choose correctly between a spontaneous decision, a plan, and a prediction.",
  b1Ep15CanDoName: "Talk about plans and intentions",
  b1Ep15Duration: "10 min",
  b1Ep15SceneTitle: "Three kinds of future",
  b1Ep15SceneBody: "You already know one way to talk about the future. Now let's tell the difference between a decision, a plan, and a prediction.",
  b1Ep15ModelExplain: "\"I'll\" is a decision made now; \"I'm going to\" is a plan made earlier; \"will\" also predicts.",
  b1Ep15ComprehensionInstruction: "Which sentence is a plan decided before now, not a decision made this second?",
