  b1Ep15BlankHint: "Two words, a contraction of \"I will\".",
  b1Ep15OpenInstruction: "Decide right now, and say what you'll have.",
  b1Ep15OpenInstruction2: "Tell me about a plan you already made.",
  b1Ep15OpenInstruction3: "Make a prediction about tomorrow's weather.",
  b1Ep16Title: "Someday",
  b1Ep16Goal: "Say what you hope or want to do in the future, with no fixed date.",
  b1Ep16CanDoName: "Talk about hopes and ambitions",
