  b1RetryPromptFollowUpForm: "Ask a real follow-up question.",
  b1RetryExplainFollowUpRepeat: "A follow-up question asks something new — try asking about a detail.",
  b1RetryPromptFollowUpRepeat: "Ask something different from what I just said.",
  b1RetryPromptSummaryEmpty: "Summarize what I just told you, in your own words.",
  b1PraiseSummaryIndependent: "Great — a clear, accurate summary.",
  b1PraiseSummaryHelped: "Nice — that restates the main point.",
  b1RetryExplainSummaryContent: "Good start — now add a bit more of what I actually said.",
  b1RetryPromptSummaryContent: "Add more detail to your summary.",
